DROP TABLE IF EXISTS `orders`;
CREATE TABLE `orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `order_number` varchar(100) NOT NULL,
  `invoice_number` varchar(255) NOT NULL,
  `order_date` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `customer_id` bigint(20) unsigned NOT NULL COMMENT 'who placed the order',
  `manager_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Who placed the order (Manager detls) ',
  `extra_gst` varchar(255) DEFAULT NULL,
  `delivery_charge` double DEFAULT 0,
  `delvry_free_after` double DEFAULT 0,
  `total_amount` varchar(255) NOT NULL,
  `ordered_from` enum('1','2') NOT NULL DEFAULT '1' COMMENT '1=>from backend, 2=>online shop',
  `comment` text DEFAULT NULL,
  `status` enum('0','1','2','3','4') NOT NULL DEFAULT '1' COMMENT '0=>Incomplt,1=>Complete,4=>Cancel Request from Frontend ,2=>cancelled,3=>Partial Return',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `orders_customer_id_foreign` (`customer_id`),
  KEY `orders_manager_id_foreign` (`manager_id`),
  CONSTRAINT `orders_customer_id_foreign` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `orders_manager_id_foreign` FOREIGN KEY (`manager_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1467 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

